import { mkdirSync, writeFileSync } from 'node:fs';

const joins = [
  ['users', 'orders', 'user_id'],
  ['orders', 'items', 'order_id'],
  ['items', 'products', 'product_id'],
];
const rows = joins.map(([left, right, key]) => `<tr><td>${left}</td><td>${right}</td><td>${key}</td></tr>`).join('\n';
mkdirSync(new URL('../scratch/', import.meta.url), { recursive: true });
writeFileSync(
  new URL('../scratch/joins.html', import.meta.url),
  `<!doctype html><style>td { padding: 4px 10px; border-bottom: 1px solid var(--border); }</style><table>${rows}</table>`,
);
